import {
  Group,
  Mesh,
  PlaneGeometry,
  Texture,
  LinearFilter,
  RepeatWrapping,
  sRGBEncoding,
  Color
} from 'three/webgpu';
import {
  MeshBasicNodeMaterial,
  color,
  texture,
  uv,
  vec2
} from 'three/tsl';
import gsap from 'gsap';
import * as primitives from '@/primitives';
import * as textUtils from '@/text';

export default function createNode(config, ctx) {
  // Root container
  const root = new Group();
  const placement = config.scenePlacement || {};
  const pos = placement.position || [0, 0, 0];
  const rot = placement.rotation || [0, 0, 0];
  const scl = placement.scale || [1, 1, 1];
  root.position.set(pos[0], pos[1], pos[2]);
  root.rotation.set(rot[0], rot[1], rot[2]);
  root.scale.set(scl[0], scl[1], scl[2]);

  // ---------- Background Plane ----------
  const imgUrl = (config.assets && config.assets.imageUrl) || '';
  const bgTexture = ctx.textureLoader(imgUrl);
  if (bgTexture instanceof Texture) {
    bgTexture.encoding = sRGBEncoding;
    bgTexture.minFilter = LinearFilter;
    bgTexture.magFilter = LinearFilter;
    bgTexture.wrapS = RepeatWrapping;
    bgTexture.wrapT = RepeatWrapping;
  }

  const bgMaterial = new MeshBasicNodeMaterial();
  bgMaterial.mapNode = texture(bgTexture);
  bgMaterial.transparent = true;
  // optional solid color overlay (none specified)
  bgMaterial.colorNode = color(new Color(0xffffff));

  const planeGeo = new PlaneGeometry(1, 1);
  const bgMesh = new Mesh(planeGeo, bgMaterial);
  bgMesh.name = 'bg-plane';
  root.add(bgMesh);

  // ---------- Text Plane ----------
  // Using the font atlas texture supplied by the context
  const atlasTex = ctx.fontAtlas;
  const atlasRegion = (config.atlasRegion && config.atlasRegion.sourceRect) || [0, 0, 512, 320];
  const [regionX, regionY, regionW, regionH] = atlasRegion;

  let uvNode;
  if (atlasTex && atlasTex.image) {
    const texW = atlasTex.image.width;
    const texH = atlasTex.image.height;
    const scaleX = regionW / texW;
    const scaleY = regionH / texH;
    const offsetX = regionX / texW;
    const offsetY = regionY / texH;
    uvNode = uv()
      .multiply(vec2(scaleX, scaleY))
      .add(vec2(offsetX, offsetY));
  } else {
    uvNode = uv();
  }

  const textMaterial = new MeshBasicNodeMaterial();
  textMaterial.mapNode = texture(atlasTex, uvNode);
  textMaterial.transparent = true;
  textMaterial.depthWrite = false;
  // Apply text color (ink) if defined
  const inkHex = (config.visual && config.visual.colors && config.visual.colors.ink) || '#16161d';
  textMaterial.colorNode = color(new Color(inkHex));

  const textMesh = new Mesh(planeGeo, textMaterial);
  textMesh.name = 'text-plane';
  root.add(textMesh);

  // ---------- Cinematic Primitives ----------
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const primitive of config.cinematicPrimitives) {
      const fn = ctx.primitives[primitive.name];
      if (typeof fn === 'function') {
        fn(root, primitive.params);
      }
    }
  }

  // ---------- Event Handlers ----------
  root.userData.handlers = {};

  // ---------- Cleanup ----------
  const timelines = []; // collect any GSAP timelines if created later
  root.userData.cleanup = function () {
    // Dispose geometries and materials
    bgMesh.geometry.dispose();
    bgMaterial.dispose();
    textMesh.geometry.dispose();
    textMaterial.dispose();

    // Dispose textures if they were created here (not the shared atlas)
    if (bgTexture && bgTexture instanceof Texture) {
      bgTexture.dispose();
    }

    // Kill GSAP timelines
    timelines.forEach(tl => tl.kill());
    timelines.length = 0;
  };

  return root;
}
